class Solution {
public:
   vector<int> productExceptSelf(vector<int>& nums) {
    int n = nums.size();
    vector<int> result(n, 1);

    int left = 1, right = 1;
    for (int i = 0; i < n; ++i) {
        result[i] *= left;
        left *= nums[i];

        result[n - 1 - i] *= right;
        right *= nums[n - 1 - i];
    }

    return result;
}
};
